import { DatePickerViewMode } from '@src/components';
import { Dayjs } from 'dayjs';
export interface DateGridSharedContract {
    viewDate: Dayjs;
    viewMode: DatePickerViewMode;
    availableViewModes: DatePickerViewMode[];
    /** If true, the presenter will display two input fields for a range. If false, a single input field is displayed. */
    isRange: boolean;
    value: [Dayjs | null, Dayjs | null];
    now: Dayjs;
    disabledDate: (date: Dayjs, info: {
        type: 'date' | 'preset';
        from?: Dayjs;
        to?: Dayjs;
    }) => boolean;
    selectionPhase: 'start' | 'end' | 'idle';
    handleValueChange: (value: [Dayjs | null, Dayjs | null]) => void;
    handleViewChange: (viewDate: Dayjs, viewMode: DatePickerViewMode) => void;
}
